corrected_code:
router.get('/notifications/channels/:channelId/rules', koaJwt({ secret: process.env.JWT_SECRET }), async (ctx) => {
  const { channelId } = ctx.params;

  const channel = await NotificationChannel.findOne({
    _id: channelId,
    userId: ctx.state.user.id
  });
  if (!channel) {
    ctx.status = 403;
    ctx.body = { message: 'Access denied to notification channel' };
    return;
  }

  ctx.body = {
    channelId: channel._id,
    deliveryType: channel.deliveryType,
    destinationWebhook: channel.webhookUrl,
    filterTags: channel.subscribedTags
  };
});
